import{_ as i,l,o as e,c as o,v as t,p as n,x as r,d as m,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"对称与非对称","description":"","frontmatter":{"title":"对称与非对称","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/symmetric-asymmetric-quant.md","filePath":"llm/symmetric-asymmetric-quant.md","lastUpdated":1789023840000}'),d={name:"llm/symmetric-asymmetric-quant.md"};function _(c,a,A,h,B,u){const s=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="对称与非对称" tabindex="-1">对称与非对称 <a class="header-anchor" href="#对称与非对称" aria-label="Permalink to &quot;对称与非对称&quot;">​</a></h1><div class="epigraph"><p>对称格子强制零映射到零，只用一个尺度；非对称加一个零点，用同样的 bit 去覆盖偏移的动态范围。激活的 ReLU 后分布常常需要后者，权重的零均值常常只需要前者。</p><footer>—— 对照仿射量化 $x \\approx s(q-z)$ 与对称 $x \\approx s q$；实现见各框架量化配置</footer></div><p><a href="/llm/uniform-nonuniform-quant">上一课</a> 在均匀与非均匀之间做了选择。本课留在均匀格子内： <strong>对称 vs 非对称（仿射）</strong>。缺口是零点 \\(z\\) 省的是哪一段范围、以及它如何破坏「整数 GEMM 不带偏置」的快路径。<a href="/llm/gptq">GPTQ</a> 实现里对称/非对称是检查点契约；本课只讲几何，不重做 Hessian。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称：\\(q = \\mathrm{clip}(\\mathrm{round}(x/s))\\)，\\(q\\in\\{-2^{b-1},\\ldots,2^{b-1}-1\\}\\)，\\(x\\approx s q\\)。零精确可表，乘法是整数乘再 scale。若 \\(x\\) 的分布不关于零对称（ReLU 激活全非负，或某通道永远偏正），一半码字浪费在永远用不到的负半轴，有效 \\(b\\) 少一 bit。</p><p>非对称：\\(x\\approx s(q-z)\\)，\\(z\\) 把格子滑到 \\([\\min,\\max]\\)。同样 \\(b\\) bit 覆盖实际动态范围。代价：\\(z\\) 要存、要在反量化里减；GEMM 出现交叉项 \\(s(W_q-z_W)(X_q-z_X)\\)，展开后有额外的求和，核更肥，或必须把减 \\(z\\) 融进打包。问题是 <strong>准一点的格子 vs 能不能走对称 INT 核</strong>。</p><p><span class="marginnote">有的实现用「无符号对称」对付 ReLU：只量化到 \\([0,2^b-1]\\) 再乘 \\(s\\)，零点固定为 0。这是非对称的退化，元数据更少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>权重：常近零均值，对称 INT4/INT8 足够，<a href="/llm/gptq">GPTQ</a> 默认对称或分组对称很常见。激活：W8A8 时非对称更常见，因为激活 min/max 不对称；SmoothQuant 迁移后仍可能不对称。KV cache 量化更要看正负是否对称，以及是否按头/按通道。</p><p>校准（后课）分别估 \\(s\\) 和 \\(z\\)：对称只用 \\(\\max|x|\\) 或百分位；非对称用 \\(\\min,\\max\\) 或百分位对。Clip 过猛会把 \\(z\\) 估偏。</p>',10)),(e(),n(E,null,{default:r(()=>[p(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E5%BC%A0%E9%87%8F%E5%88%86%E5%B8%83%22%5D%20--%3E%20SYM%7B%22%E8%BF%91%E4%BC%BC%E9%9B%B6%E5%AF%B9%E7%A7%B0%3F%22%7D%0A%20%20SYM%20--%3E%7C%E6%98%AF%7C%20S%5B%22%E5%AF%B9%E7%A7%B0%3A%20%E5%8F%AA%E5%AD%98%20s%22%5D%0A%20%20SYM%20--%3E%7C%E5%90%A6%7C%20A%5B%22%E4%BB%BF%E5%B0%84%3A%20%E5%AD%98%20s%20%E4%B8%8E%20z%22%5D%0A%20%20S%20--%3E%20GEMM%5B%22%E6%95%B4%E6%95%B0%20GEMM%20%E5%BF%AB%E8%B7%AF%E5%BE%84%22%5D%0A%20%20A%20--%3E%20EXTRA%5B%22%E5%B1%95%E5%BC%80%E4%BA%A4%E5%8F%89%E9%A1%B9%E6%88%96%E5%85%88%E5%87%8F%E9%9B%B6%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>推理核：若只重量化、激活仍 FP16（W4A16），零点只出现在反量化权重的一乘加里，代价小，非对称更划算。若 W8A8 两端都是整数，零点成本高，有时宁可对称 + 稍微更差的 \\(s\\)，换核的吞吐。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>仿射的交叉项：\\(s_W s_X \\sum (q_W q_X - q_W z_X - z_W q_X + z_W z_X)\\)。后三项可预计算或作向量加，但寄存器与带宽增加。对称 \\(z=0\\)，只留第一项，硬件友好。这是「非对称更准但更慢」的机制，不是感觉。</p><p>数值：零点本身通常 8 bit 或 32 bit 存。分组很细时，零点元数据吃回每参数比特，和 QLoRA 双重量化面对的尺度问题同类。后课粒度会限制你把 \\(z\\) 存多细。</p><p><span class="marginnote">对称量化对「必须精确的零」（稀疏、ReLU 硬零、mask）更友好：量化后仍是零。非对称可能把真零映成非零，破坏稀疏核的跳过。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 W4A16 上因为「对称更简单」就浪费激活本不存在的负半轴——权重对称、激活另一套是正常的。不要混用带 \\(z\\) 与不带 \\(z\\) 的检查点。不要假设所有 INT8 Tensor Core 路径都接受逐通道零点。下一课粒度：同一 \\(s,z\\) 共享的范围有多大。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对称：零对齐、GEMM 简单；浪费不对称分布的半边码字。</li><li>非对称：格子对准 min/max，多存零点，整数 GEMM 有交叉项。</li><li>权重常对称；激活与 KV 常要仿射或无符号。</li><li>W4A16 的零点便宜；W8A8 的零点可能卖掉吞吐。</li><li>出处：仿射量化标准形式；GPTQ / 框架里的对称开关。</li></ul>',9))])}const T=i(d,[["render",_]]);export{x as __pageData,T as default};
